    void drawHeatmap(Canvas cn){title(cn,"EFT Load / Risk Heatmap");int w=getWidth();float l=w*.07f,r=w*.95f,y=dp(210);drawTank(cn,l,r,y);double mx=0;for(double f:c.fi)mx=Math.max(mx,f);for(int i=0;i<c.n;i++){float x=l+(float)(c.x[i]/c.L)*(r-l);double u=c.fi[i]/mx;p.setStyle(Paint.Style.FILL);p.setColor(u<.55?GREEN:(u<.8?YELLOW:RED));cn.drawCircle(x,y,dp(10)+(float)dp(15)*(float)u,p);t.setColor(Color.WHITE);t.setTextSize(dp(7));cn.drawText("S"+(i+1),x-dp(7),y+dp(38),t);}drawGroupLegend(cn,dp(420));}
    void drawCompare(Canvas cn){title(cn,"Topology Compare");float y=dp(120);for(int l=1;l<=3;l++)for(int a=2;a<=6;a++){double demand=c.designF/a,util=demand/Math.max(1,d(actCapacity));double score=Math.max(0,100-Math.abs(.72-util)*42-a*2.5-l*4);float x=dp(18)+(a-2)*dp(66),yy=y+(l-1)*dp(110);p.setStyle(Paint.Style.FILL);p.setColor(score>70?GREEN:(score>45?YELLOW:RED));cn.drawRoundRect(new RectF(x,yy,x+dp(56),yy+dp(78)),dp(6),dp(6),p);t.setColor(Color.WHITE);t.setTextSize(dp(8));cn.drawText("L"+l+" A"+a,x+dp(6),yy+dp(20),t);cn.drawText(String.format(Locale.US,"%.0f",score),x+dp(15),yy+dp(49),t);}}
    void drawReview(Canvas cn){title(cn,"Design Review");String[] rows={"CONFIG: "+c.layers+" layers / "+c.nAct+" actuators","Layer beam counts: "+Arrays.toString(c.layerBeamCount),String.format(Locale.US,"Max actuator group %.1f kN",max(c.actLoads)),String.format(Locale.US,"Moment error %.2f%%",c.mErr),String.format(Locale.US,"Beam stress %.1f MPa",c.beamStress),String.format(Locale.US,"Pad pressure %.2f MPa",c.padPressure),"Check deformed geometry, catalog ratings and fixture FEM before release."};textBlock(cn,rows,dp(18),dp(120));}
    void arrow(Canvas cn,float x,float y,float dx,float dy,int col){p.setColor(col);p.setStrokeWidth(4);cn.drawLine(x,y,x+dx,y+dy,p);}
