  double std(double v){double[]a={10,20,25,50,75,100,150,200,250,300,500,750,1000};for(double x:a)if(x>=v)return x;return Math.ceil(v/100)*100;}double d(EditText e){return Double.parseDouble(e.getText().toString().trim().replace(',','.'));}int clamp(int v,int a,int b){return Math.max(a,Math.min(b,v));}int dp(int x){return(int)(x*getResources().getDisplayMetrics().density+.5f);}LinearLayout.LayoutParams lp(){LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(4),0,dp(4));return p;}TextView tx(String s,int z,boolean b,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setTypeface(Typeface.DEFAULT,b?Typeface.BOLD:Typeface.NORMAL);return v;}TextView card(String s,int c){TextView v=tx(s,13,false,Color.WHITE);v.setPadding(dp(10),dp(10),dp(10),dp(10));v.setBackground(bg(c,10));return v;}GradientDrawable bg(int c,int r){GradientDrawable g=new GradientDrawable();g.setColor(c);g.setCornerRadius(dp(r));return g;}
